239→    zone,
240→    zipCodes,
241→    minOrderAmount,
242→    deliveryFee,
243→    freeShippingAbove,
244→    estimatedDays,
245→    cutoffTime,
246→    selectedDays,
247→    priority,
248→    fetcher,
249→    resetForm,
