317→        aria-label={rule.isActive ? "Deactivate" : "Activate"}
318→      >
319→        <span
320→          style={{
321→            position: "absolute",
322→            top: "2px",
323→            left: rule.isActive ? "20px" : "2px",
324→            width: "18px",
325→            height: "18px",
326→            borderRadius: "50%",
327→            backgroundColor: "#fff",
