389→                  "text",
390→                  "text",
391→                  "text",
392→                  "text",
393→                  "text",
394→                  "text",
395→                ]}
396→                headings={[
397→                  "Rule Name",
398→                  "Zone",
399→                  "Delivery Fee",
400→                  "Min. Order",
401→                  "ETA",
402→                  "Days",
403→                  "Actions",
