   138→  // Fetch the most relevant active DeliveryRule for this zip.
   139→  // Priority 1: rules that explicitly list this zip in their zipCodes field.
   140→  // Priority 2: rules that match by zone (with no explicit zip list).
   141→  // Within each priority tier, order by `priority ASC` (lower = higher priority).
   142→  const zipCodeUpper = normalizedZip;
