   154→  // Pass 1: explicit zip match — zipCodes field contains this zip code
   155→  for (const rule of activeRules) {
   156→    if (rule.zipCodes) {
   157→      const zips = rule.zipCodes.split(",").map((z) => z.trim().toUpperCase());
   158→      if (zips.includes(zipCodeUpper)) {
